use super::{native_appearance_inspection as a,native_appearance_layer_study as layer,native_appearance_occlusion_study as scene,native_appearance_replay_study_tests as fixture,native_resources as resources,sprite,compositor::Canvas};
use std::{fs,path::{Path,PathBuf},sync::atomic::AtomicBool};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn pin(path:&Path)->Value{let b=fs::read(path).unwrap();json!({"path":path,"bytes":b.len(),"sha256":sha(&b)})}
fn byte_pin(v:&Value)->resources::BytePin{let s=v["sha256"].as_str().unwrap();resources::BytePin{bytes:v["bytes"].as_u64().unwrap(),sha256:(0..32).map(|i|u8::from_str_radix(&s[i*2..i*2+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap()}}
fn input(delta:(i32,i32),first:bool)->scene::Inputs{scene::Inputs{prop_delta:Some(delta),player_first:Some(first),prop_flags:Some(0)}}
fn literal_oracle<'s>(player:&[layer::Submission<'s>],prop:Option<&'s sprite::SpriteFrame>,delta:(i32,i32),first:bool)->Canvas{
 let mut list=Vec::new();let add_player=|list:&mut Vec<(&'s sprite::SpriteFrame,i32,i32,bool)>|{for s in player{list.push((s.frame,0,0,s.kind=="shadow"));}};
 if first{add_player(&mut list);if let Some(f)=prop{list.push((f,delta.0,delta.1,false));}}else{if let Some(f)=prop{list.push((f,delta.0,delta.1,false));}add_player(&mut list);}
 let mut fragments=Vec::new();let mut insertion=0u64;for(f,dx,dy,shadow)in list{let source=f.fragments.as_ref().unwrap();for r in &source.references{let x=32680+2*i64::from(dx)+i64::from(r.half_x);let y=32784+i64::from(dy)+i64::from(r.y);let row=2*y-(x&!1);let col=((x+1)&!1)+2*y;fragments.push(((row,col,r.depth,std::cmp::Reverse(insertion)),source,r.block_id,shadow));insertion+=1;}}
 fragments.sort_by_key(|v|v.0);let mut c=Canvas::new(320,300).unwrap();c.clear([18,25,35]);for((row,col,_,_),source,id,shadow)in fragments{let mut rgba=[0u8;24*24*4];source.atlas[id as usize].write_rgba(&mut rgba);let x=i32::try_from(136+12*(col-98248)).unwrap();let y=i32::try_from(198+6*(row-32888)).unwrap();if shadow{c.blit_native_shadow_rgb555(&rgba,24,24,x,y).unwrap();}else{c.blit_rgba(&rgba,24,24,x,y).unwrap();}}c
}
#[test]fn actual_FirePot_rear_front_occlusion_and_distinct_body_subframe_depth_ties(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let d=a::nad(&fixed.bytes("resources/appearance-dependencies.nad")).unwrap();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let trace:Value=serde_json::from_slice(&fixed.bytes("appearance-layer-trace.json")).unwrap();let bank=fixed.bank(&d,&trace,88);let model=layer::Model::new(true,b,b,b.observed,1).unwrap();let player=model.submissions(b,b.observed,88,0,&bank.body,&bank.shadow,&bank.layer,fixture::inputs()).unwrap();
 // Immutable Native archive provider; selected38-0 member read has no Shared
 // fallback and preserves its actual source fragment coordinates and depths.
 let provider_path=project.join("target/r425-native-dm564-fixture/consumer-input.json");let provider:Value=serde_json::from_slice(&fs::read(&provider_path).unwrap()).unwrap();let archives=provider["archive_pins"].as_array().unwrap();let idx=archives.iter().find(|v|v["path"].as_str().unwrap().ends_with("LTsprite.idx")).unwrap();let pak=archives.iter().find(|v|v["path"].as_str().unwrap().ends_with("LTsprite.pak")).unwrap();let archive_root=PathBuf::from(idx["path"].as_str().unwrap()).parent().unwrap().to_owned();let bytes=resources::read_native_inspection_member(&archive_root,false,byte_pin(idx),byte_pin(pak),"38-0.spr",&AtomicBool::new(false)).unwrap();let prop=sprite::decode_world_spr_with_limits(&bytes,sprite::SpriteLimits{max_input_bytes:1024*1024,max_frames:32,max_blocks:4096,max_block_references:32768,max_frame_dimension:1024,max_total_pixels:4*1024*1024}).unwrap();assert_eq!(prop.frames.len(),11);
 let input_root=project.join("target/r450-scene-inputs");fs::create_dir_all(&input_root).unwrap();let selected_path=input_root.join("38-0.spr");fs::write(&selected_path,&bytes).unwrap();let extra=vec![pin(&provider_path),pin(Path::new(idx["path"].as_str().unwrap())),pin(Path::new(pak["path"].as_str().unwrap())),pin(&selected_path)];let out=project.join("target/r450-scene-occlusion-cpu");fs::create_dir_all(&out).unwrap();let mut images=Vec::new();let mut rows=Vec::new();let mut scene=scene::Scene::new(true,b,b,b.observed,8).unwrap();let mut baseline=0;let mut front=0;let mut rear=0;
 for(name,delta,with_prop)in[("player-alone",(0,0),false),("prop-rear",(1,-1),true),("prop-same",(0,0),true),("prop-front",(-1,1),true)]{let p=if with_prop{Some(&prop.frames[0])}else{None};let f=scene.render(b,b.observed,&player,p,input(delta,true)).unwrap();let oracle=literal_oracle(&player,p,delta,true);assert_eq!(f.canvas.rgba(),oracle.rgba());if !with_prop{baseline=f.body_visible_pixels;}if name=="prop-front"{front=f.body_visible_pixels;}if name=="prop-rear"{rear=f.body_visible_pixels;}
  images.push(fixture::png(&out.join(format!("{name}.png")),f.canvas.rgba(),320,300));rows.push(json!({"case":name,"prop_delta_world":delta,"player_first":true,"body_visible_pixels":f.body_visible_pixels,"prop_reference_count":f.prop_reference_count,"RGBA_sha256":sha(f.canvas.rgba())}));}
 assert!(front<baseline&&front!=rear,"Actual FirePot source depth and relative placement must change player visibility");
 // Source depths are retained. Two different actual attack subframes share
 // half-cell/depth keys, so cross-actor insertion reversal has a real effect.
 let other=&bank.body.sprite.frames[3];let refs=|f:&sprite::SpriteFrame|f.fragments.as_ref().unwrap().references.iter().map(|r|(r.half_x,r.y,r.depth)).collect::<std::collections::BTreeSet<_>>();let tie=refs(player[0].frame).intersection(&refs(other)).count();assert!(tie>0);let mut tie_hashes=Vec::new();let mut tie_visibility=Vec::new();
 for first in [true,false]{let f=scene.render(b,b.observed,&player,Some(other),input((0,0),first)).unwrap();assert_eq!(f.canvas.rgba(),literal_oracle(&player,Some(other),(0,0),first).rgba());tie_hashes.push(sha(f.canvas.rgba()));tie_visibility.push(f.body_visible_pixels);images.push(fixture::png(&out.join(format!("actual-body-tie-player-first-{first}.png")),f.canvas.rgba(),320,300));rows.push(json!({"case":"actual-body-subframes0-and3-tie","player_first":first,"source_equal_cell_depth_intersections":tie,"body_visible_pixels":f.body_visible_pixels,"RGBA_sha256":sha(f.canvas.rgba())}));}
 assert_ne!(tie_hashes[0],tie_hashes[1]);assert_ne!(tie_visibility[0],tie_visibility[1]);
 for selector in 0..3{let mut q=input((0,0),true);match selector{0=>q.prop_delta=None,1=>q.player_first=None,_=>q.prop_flags=None};assert!(scene.render(b,b.observed,&player,Some(&prop.frames[0]),q).is_err());}scene.retire();assert!(scene.render(b,b.observed,&player,None,input((0,0),true)).is_err());assert!(scene::Scene::new(false,b,b,b.observed,1).is_err());
 fs::write(project.join("logs/continuation-20261003/r450-occlusion-details.json"),serde_json::to_vec_pretty(&json!({"state":"ACTUAL_NATIVE_PROP_OCCLUSION_AND_ACTUAL_SUBFRAME_DEPTH_TIES_CONDITIONAL_CPU","scene_cases":4,"tie_order_cases":2,"rows":rows,"baseline_body_visible":baseline,"rear_body_visible":rear,"front_body_visible":front,"actual_prop_reduces_body_visibility":front<baseline,"actual_tie_reversing_changes_pixels":tie_hashes[0]!=tie_hashes[1],"source_equal_cell_depth_intersections":tie,"images":images,"input_pins":fixed.used.into_inner(),"extra_input_pins":extra,"prop_member":"38-0.spr","prop_selected_subframe":0,"prop_frame_count":11,"runtime_inputs_observed":false,"prop_default_action_qualified":false,"terrain_roof_qualified":false,"native_framebuffer_parity_qualified":false,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
